    var backToMain = shellIconButton('dsh-mobile-back-main', '回到主会话', ICON_BACK_MAIN)
    // ★ 初值按"不显示"给 ✓：首帧还没数过面包屑 ✓，宁可先不显示 ✓（`syncBackToMainButton()` 会立刻纠正 ✓）
    backToMain.dataset.dshmShown = '0'

