    if (fileNameUnits(text) <= limit) return { head: stem, ext: ext }
    // 没有扩展名 ⇒ 普通尾部省略（留头 ✓）—— 这是"退化"那条路 ✓
    if (ext === '') return { head: fileNameHead(text, limit - 1) + '\u2026', ext: '' }
    var room = limit - 1 - fileNameUnits(ext)
